  function toast(msg,type='ok'){const el=$('#toast');if(!el)return;el.textContent=msg;el.className='toast show'+(type==='err'?' err':'');clearTimeout(toast.t);toast.t=setTimeout(()=>el.className='toast',2800);}
  function nextUiFrame(){return new Promise(resolve=>{const raf=typeof requestAnimationFrame==='function'?requestAnimationFrame:(fn=>setTimeout(fn,0));raf(()=>resolve());});}
  function setPageBusy(active){const main=document.querySelector('main');document.body.classList.toggle('page-rendering',!!active);if(active){main?.setAttribute('aria-busy','true');}else{main?.removeAttribute('aria-busy');}}
  function setActionBusy(selectors,active){for(const selector of selectors||[]){for(const el of $$(selector)){if(active){if(!('teWasDisabled' in el.dataset))el.dataset.teWasDisabled=el.disabled?'1':'0';el.disabled=true;el.setAttribute('aria-busy','true');}else{el.disabled=el.dataset.teWasDisabled==='1';delete el.dataset.teWasDisabled;el.removeAttribute('aria-busy');}}}}
  async function runUiAction(key,selectors,task){if(uiActions.has(key))return false;uiActions.add(key);setActionBusy(selectors,true);try{await nextUiFrame();await task();return true;}catch(err){console.error(`UI action ${key} failed`,err);toast('That action could not finish. Please try again.','err');return false;}finally{setActionBusy(selectors,false);uiActions.delete(key);}}
  function queuePlanCalculation(task){const request=++planUpdateSeq;const run=async()=>{if(request!==planUpdateSeq)return false;return runUiAction('team-plan-calc',['#buildTeamPlanBtn','#refreshPlanTacticsBtn'],async()=>{if(request!==planUpdateSeq)return;await task();});};planUpdateChain=planUpdateChain.catch(err=>{console.warn('Previous Team Plan calculation failed',err);}).then(run);return planUpdateChain;}
  function roleAsset(pos){return `assets/roles/${P.roleGroup(pos)}.webp`;}
