  function drillCategoryLabel(cat){const c=String(cat||'').toLowerCase();if(c.includes('attack'))return'Attacking';if(c.includes('defence')||c.includes('defense'))return'Defending';if(c.includes('possession'))return'Possession';if(c.includes('physical')||c.includes('mental'))return'Physical & Mental';return String(cat||'Drill');}
