  // ---------- Player profile ----------
  function profileGroups(player){return player.position==='GK'?D.GROUPS_GK:D.GROUPS_OUTFIELD;}
  function weakestKeySkills(player,limit=6){const white=new Set(D.whiteSkillsForRoles(P.normaliseRoles(player)));return Object.entries(player.skills||{}).filter(([name,v])=>white.has(name)&&Number.isFinite(Number(v))).sort((a,b)=>Number(a[1])-Number(b[1])||a[0].localeCompare(b[0])).slice(0,limit);}
  function abilityChoicesForRoles(roles,selected=[]){const eligible=new Set(D.specialAbilitiesForRoles?.(roles)||[]),kept=new Set((selected||[]).map(D.canonicalSpecialAbilityName).filter(Boolean));return D.SPECIAL_ABILITIES.filter(a=>eligible.has(a)||kept.has(a));}
  function renderProfileAbilities(){const roles=[...new Set([...currentEditRoles(),...state.profilePreservedRoles])],eligible=new Set(D.specialAbilitiesForRoles?.(roles)||[]),choices=abilityChoicesForRoles(roles,state.profileAbilities);$('#profileAbilityPicker').innerHTML=choices.map(a=>`<button type="button" class="chip profile-ability-chip ${state.profileAbilities.includes(a)?'active':''} ${eligible.has(a)?'':'outside-role'}" data-profile-ability="${esc(a)}" title="${eligible.has(a)?'Eligible for current natural roles':'Existing ability preserved outside current role filter'}">${esc(a)}${eligible.has(a)?'':' · saved'}</button>`).join('')||'<span class="mini-note">Choose at least one natural role to see eligible Special Abilities.</span>';}
  function renderProfileRelated(){const natural=new Set([...currentEditRoles(),...state.profilePreservedRoles]);state.profileRelatedRoles=state.profileRelatedRoles.filter(r=>!natural.has(r));$('#profileRelatedPicker').innerHTML=D.ALL_POSITIONS.filter(a=>!natural.has(a)).map(a=>`<button type="button" class="chip ${state.profileRelatedRoles.includes(a)?'active':''}" data-profile-related="${a}">${a}</button>`).join('');}
  function fillRoleSelect(id,value,allowBlank=false,allowed=D.ALL_POSITIONS){$(id).innerHTML=(allowBlank?'<option value="">None</option>':'')+allowed.map(r=>`<option value="${r}" ${r===value?'selected':''}>${r}</option>`).join('');}
  function playstyleOptions(roles,current){const allowed=D.playstylesForRoles(roles),currentName=typeof current==='object'?P.playstyleName({playstyle:current}):String(current||'');const legacy=currentName&&!allowed.includes(currentName)?`<option value="${esc(currentName)}" selected>${esc(currentName)} (preserved)</option>`:'';return '<option value="">No playstyle</option>'+legacy+allowed.map(x=>`<option value="${esc(x)}" ${x===currentName?'selected':''}>${esc(x)}</option>`).join('');}
  function playstyleLevelLabel(ps){
    if(!ps?.type)return 'No playstyle';
    const level=Number(ps.level)||0;
    if(level===0)return 'Level not captured';
    return B.PLAYSTYLE_LEVELS.find(x=>x.id===level)?.name||`Level ${level}`;
  }
  function playstyleLevelOptions(current=0,hasPlaystyle=true){
    const n=Number(current)||0;
    const rows=B.PLAYSTYLE_LEVELS.filter(x=>x.id>=1);
    return `<option value="">${hasPlaystyle?'Tier not captured':'No playstyle'}</option>`+rows.map(x=>`<option value="${x.id}" ${x.id===n?'selected':''}>${esc(x.name)}</option>`).join('');
  }
  function renderPlaystyleState(p){
    const ps=P.normalisePlaystyle(p.playstyle),rows=[];
    if(ps.points!=null)rows.push(['Points',ps.points]);
    if(ps.nextLevelProgress!=null)rows.push(['Next-level progress',ps.nextLevelProgress]);
    if(ps.nextLevelPrice!=null)rows.push(['Next-level price',ps.nextLevelPrice]);
    if(ps.isTrainingNextLevel!=null)rows.push(['Training next level',ps.isTrainingNextLevel?'Yes':'No']);
    if(ps.isNextLevelAvailable!=null)rows.push(['Next level available',ps.isNextLevelAvailable?'Yes':'No']);
    if(ps.boost!=null)rows.push(['Captured boost',Array.isArray(ps.boost)?JSON.stringify(ps.boost):ps.boost]);
    $('#profilePlaystyleState').innerHTML=rows.map(([k,v])=>`<div><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('');
    $('#profilePlaystyleCard').style.display=rows.length?'block':'none';
  }
  async function renderPlayerProfile(){
    if(!state.playerKey){go('squad',{historyMode:'replace'});return;}
    const p=await P.get(state.playerKey);if(!p){toast('Player could not be loaded','err');state.playerKey='';go('squad',{historyMode:'replace'});return;}
    // Paint the core identity first so a secondary intelligence panel can never leave a blank profile.
    const displayName=String(p.name||'Player').trim().split(/\s+/),firstName=displayName.shift()||'Player',restName=displayName.join(' ');$('#profileName').innerHTML=`<span>${esc(firstName)}</span>${restName?` <em>${esc(restName)}</em>`:''}`;$('#profileOvr').textContent=p.ovr||'—';$('#profileEyebrow').textContent='Player Profile';
    const roles=P.normaliseRoles(p),related=P.normaliseRelatedRoles(p),white=new Set(typeof D.whiteSkillsForRoles==='function'?D.whiteSkillsForRoles(roles):[]);
    $('#profileRoleArt').src=roleAsset(p.position);$('#profileRoleArt').alt=`${P.roleGroup(p.position).toUpperCase()} role artwork`;
    $('#profileMeta').innerHTML=`<span class="profile-role-label">Roles</span>${roles.map((r,i)=>`<button type="button" class="profile-role-chip ${i===0?'primary':''}" data-profile-primary-role="${esc(r)}">${esc(r)}${i===0?' · primary':''}</button>`).join('')}${related.length?`<span>Related ${esc(related.join('/'))}</span>`:''}${p.age?`<span>Age ${esc(p.age)}</span>`:''}`;
    const badgeCards=[],ps=P.playstyleName(p);
    if(ps)badgeCards.push(`<div class="identity-card"><img src="${playstyleIcon(ps,p.playstyle)}" alt=""><div><span>Playstyle</span><b>${esc(ps)}</b><small>${esc(playstyleLevelLabel(p.playstyle))}</small></div></div>`);
    for(const a of p.specialAbilities||[])badgeCards.push(`<div class="identity-card gold"><img src="${abilityIcon(a)}" alt=""><div><span>Special Ability</span><b>${esc(a)}</b></div></div>`);
    if(p.specialAbilityTraining?.active)badgeCards.push(`<div class="identity-card learning"><div class="learning-icon">↗</div><div><span>Special Ability</span><b>Training in progress</b><small>Not counted as unlocked</small></div></div>`);
    $('#profileBadges').innerHTML=badgeCards.join('')||'<div class="profile-badge">No playstyle or Special Ability selected</div>';
    const facts=[];if(p.condition!=null&&p.condition!=='')facts.push(['Condition',`${esc(p.condition)}%`]);if(p.availability!=null&&p.availability!=='')facts.push(['Availability',esc(p.availability)]);if(p.morale!=null&&p.morale!=='')facts.push(['Morale',esc(p.morale)]);$('#profileFacts').innerHTML=facts.map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('');$('#profileFacts').style.display=facts.length?'grid':'none';
    renderPlaystyleState(p);
    const weak=weakestKeySkills(p);$('#profileKeySkills').innerHTML=weak.length?weak.map(([name,v])=>`<div class="profile-key"><span>${esc(name)}</span><div class="track"><i style="width:${Math.max(3,Math.min(100,Number(v)/2.5))}%"></i></div><b>${esc(v)}</b></div>`).join(''):'<div class="empty"><b>No skill data</b>Update this player from a scan to populate attributes.</div>';const insight=$('#profileDevelopmentInsight');if(insight){insight.innerHTML=weak.length?`<span>🏆</span><div><b>Development insight</b><p>Focus on ${weak.slice(0,3).map(x=>esc(x[0])).join(', ')} to strengthen this player’s weakest key attributes.</p></div>`:'<span>↻</span><div><b>Development insight</b><p>Update this player from a Skills scan to unlock targeted development guidance.</p></div>'; }
    $('#profileRoleScores').innerHTML=roles.map(role=>{const rs=F.roleStats(p,role);if(!rs)return'';const all=rs.keys.map(a=>({attribute:a,value:Number(p.skills?.[a])})).filter(x=>Number.isFinite(x.value)),strong=[...all].sort((a,b)=>b.value-a.value||a.attribute.localeCompare(b.attribute)).slice(0,3),weakest=[...all].sort((a,b)=>a.value-b.value||a.attribute.localeCompare(b.attribute)).slice(0,3);return `<div class="role-score-card"><div class="role-score-summary"><div class="role-score-badge">${esc(role)}</div><div><small>Role score</small><b>${fmt(rs.roleMean,1)}</b></div></div><div class="role-score-split"><div><small>Strongest 3</small>${strong.map(x=>`<i>${esc(x.attribute)} <b>${esc(x.value)}</b></i>`).join('')}</div><div><small>Weakest 3</small>${weakest.map(x=>`<i>${esc(x.attribute)} <b>${esc(x.value)}</b></i>`).join('')}</div></div></div>`;}).join('')||'<div class="empty">Role score needs complete visible attributes.</div>';
    $('#profileSkills').innerHTML=Object.entries(profileGroups(p)).map(([group,names])=>`<div class="skill-group"><h3>${esc(group)}</h3><div class="skill-grid">${names.map(name=>{const value=p.skills?.[name],n=Number(value);return `<div class="skill ${white.has(name)?'white':'grey'}"><span>${esc(name)}</span><div class="skill-track"><i style="width:${Number.isFinite(n)?Math.max(3,Math.min(100,n/2.5)):0}%"></i></div><b>${esc(value??'—')}</b></div>`}).join('')}</div></div>`).join('');
    $('#profileEditCard').style.display='none';$('#profileEditBtn').textContent='Edit Player';$('#profileEditNote').textContent=p.legacyRoles?.length?`Legacy roles preserved but not selectable: ${p.legacyRoles.join(', ')}`:'';
  }
  async function openProfileEdit(){
    const p=await P.get(state.playerKey);if(!p)return;const roles=P.normaliseRoles(p);
    state.profileAbilities=[...(p.specialAbilities||[])];state.profileRelatedRoles=[...P.normaliseRelatedRoles(p)];state.profilePreservedRoles=roles.slice(3);
    $('#profileEditName').value=p.name||'';$('#profileEditAge').value=p.age??'';$('#profileEditOvr').value=p.ovr??'';
    const allowed=p.position==='GK'?['GK']:D.ALL_POSITIONS.filter(r=>r!=='GK');
    fillRoleSelect('#profileEditRole1',roles[0]||p.position,false,allowed);fillRoleSelect('#profileEditRole2',roles[1]||'',true,p.position==='GK'?[]:allowed);fillRoleSelect('#profileEditRole3',roles[2]||'',true,p.position==='GK'?[]:allowed);
    $('#profileEditRole2').disabled=p.position==='GK';$('#profileEditRole3').disabled=p.position==='GK';$('#profileEditPlaystyle').innerHTML=playstyleOptions(roles,p.playstyle);const profilePs=P.normalisePlaystyle(p.playstyle);$('#profileEditPlaystyleLevel').innerHTML=playstyleLevelOptions(profilePs.level,!!P.playstyleName(p));$('#profileEditPlaystyleLevel').disabled=!P.playstyleName(p);
    $('#profilePreservedRolesNote').textContent=state.profilePreservedRoles.length?`Additional imported natural roles preserved: ${state.profilePreservedRoles.join(', ')}. This three-role editor will not delete them.`:'';
    renderProfileAbilities();renderProfileRelated();$('#profileEditCard').style.display='block';$('#profileEditBtn').textContent='Editing';$('#profileEditCard').scrollIntoView({behavior:'smooth',block:'start'});
  }
  function currentEditRoles(){return [$('#profileEditRole1')?.value,$('#profileEditRole2')?.value,$('#profileEditRole3')?.value].filter((r,i,a)=>r&&a.indexOf(r)===i);}
  ['#profileEditRole1','#profileEditRole2','#profileEditRole3'].forEach(id=>$(id)?.addEventListener('change',()=>{const allNatural=[...new Set([...currentEditRoles(),...state.profilePreservedRoles])];$('#profileEditPlaystyle').innerHTML=playstyleOptions(allNatural,$('#profileEditPlaystyle').value);renderProfileRelated();renderProfileAbilities();}));
  $('#profileEditPlaystyle')?.addEventListener('change',e=>{const has=!!e.target.value;$('#profileEditPlaystyleLevel').disabled=!has;$('#profileEditPlaystyleLevel').value='';});
  $('#profileBackBtn')?.addEventListener('click',()=>{if(history.state?.teTopEleven&&history.length>1)history.back();else go('squad',{historyMode:'replace'});});$('#profileTrainBtn')?.addEventListener('click',()=>{if(state.playerKey){state.trainingKey=state.playerKey;go('training');}});$('#profileRescanBtn')?.addEventListener('click',async()=>{if(!state.playerKey)return;const p=await P.get(state.playerKey);state.scanMode='update';state.scanUpdateKey=state.playerKey;await go('add-player');if($('#scanProgressText'))$('#scanProgressText').textContent=`Updating ${p?.name||'player'} · choose a fresh Skills screenshot`;toast(`Choose the screenshot · ${p?.name||'player'} will update automatically`);});$('#profileEditBtn')?.addEventListener('click',openProfileEdit);$('#profileCancelEditBtn')?.addEventListener('click',()=>{$('#profileEditCard').style.display='none';$('#profileEditBtn').textContent='Edit Player';});
  document.addEventListener('click',async e=>{const primary=e.target.closest('[data-profile-primary-role]');if(primary&&state.playerKey){const p=await P.get(state.playerKey),chosen=primary.dataset.profilePrimaryRole;if(p&&chosen){const roles=P.normaliseRoles(p),next=[chosen,...roles.filter(r=>r!==chosen)];await P.save({...p,position:chosen,roles:next},state.playerKey);toast(`${chosen} set as primary role`);await renderPlayerProfile();}return;}const b=e.target.closest('[data-profile-ability]');if(b){const a=b.dataset.profileAbility;state.profileAbilities=state.profileAbilities.includes(a)?state.profileAbilities.filter(x=>x!==a):[...state.profileAbilities,a];renderProfileAbilities();return;}const rr=e.target.closest('[data-profile-related]');if(rr){const r=rr.dataset.profileRelated;state.profileRelatedRoles=state.profileRelatedRoles.includes(r)?state.profileRelatedRoles.filter(x=>x!==r):[...state.profileRelatedRoles,r];renderProfileRelated();}});
  $('#profileSaveBtn')?.addEventListener('click',async()=>{
    const existing=await P.get(state.playerKey);if(!existing)return;
    const name=$('#profileEditName').value.trim(),age=Number($('#profileEditAge').value),ovr=Number($('#profileEditOvr').value),primary=$('#profileEditRole1').value;
    if(!name||!primary){toast('Name and primary role are required','err');return;}if(!Number.isFinite(age)||age<15||age>60){toast('Age must be between 15 and 60','err');return;}if(!Number.isFinite(ovr)||ovr<1||ovr>520){toast('OVR must be between 1 and 520','err');return;}
    const duplicate=(await P.all()).find(x=>x.key!==state.playerKey&&String(x.name||'').trim().toLowerCase()===name.toLowerCase());if(duplicate){toast('Another player already uses that name','err');return;}
    const roles=P.mergeVisibleNaturalRoles(P.normaliseRoles(existing),currentEditRoles(),3),related=state.profileRelatedRoles.filter(r=>!roles.includes(r));
    let playstyle=P.mergePlaystyleState(existing.playstyle,$('#profileEditPlaystyle').value);const profileLevel=Number($('#profileEditPlaystyleLevel').value)||0;if($('#profileEditPlaystyle').value&&profileLevel>=1)playstyle={...playstyle,level:profileLevel};
    await P.save({...existing,name,age,ovr,position:roles[0]||primary,roles,relatedRoles:related,playstyle,specialAbilities:[...state.profileAbilities]},state.playerKey);
    toast('Player updated');await renderDashboard();await renderPlayerProfile();
  });
