  // ---------- Refresh-safe scanner queue persistence ----------
  function openQueueDb(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){resolve(null);return;}const req=indexedDB.open(QUEUE_DB_NAME,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(QUEUE_STORE))req.result.createObjectStore(QUEUE_STORE);};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
  async function queueImagePut(id,dataUrl){try{const db=await openQueueDb();if(!db)return false;await new Promise((resolve,reject)=>{const tx=db.transaction(QUEUE_STORE,'readwrite');tx.objectStore(QUEUE_STORE).put(dataUrl,String(id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();return true;}catch(_){return false;}}
  async function queueImageGet(id){try{const db=await openQueueDb();if(!db)return null;const value=await new Promise((resolve,reject)=>{const tx=db.transaction(QUEUE_STORE,'readonly'),req=tx.objectStore(QUEUE_STORE).get(String(id));req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error);});db.close();return value;}catch(_){return null;}}
