  document.addEventListener('input',e=>{if(!e.target.matches('[data-scan-skill]')||!state.scan)return;const skill=e.target.dataset.scanSkill,value=Number(e.target.value);if(e.target.value===''||!Number.isFinite(value))delete state.scan.skills[skill];else state.scan.skills[skill]=value;refreshScanVerification();});


