  async function renderGeminiScannerSettings(){const el=$('#geminiScannerApiKey');if(!el)return;const key=await SC.getApiKey();el.value=key;const status=$('#geminiScannerStatus');if(status)status.textContent=key?`API key saved on this device · Gemini 3.1 Flash Live scanner · HIGH thinking · 260 exact playstyle states + 19 coloured Special Ability references. Test the connection before scanning.`:'Not configured yet. Create a Gemini API key in Google AI Studio, then test the Flash Live connection.';}
  $('#saveGeminiScannerKey')?.addEventListener('click',async()=>{const key=await SC.setApiKey($('#geminiScannerApiKey').value);scannerHealthOkAt=0;scannerUpdateHealthOkAt=0;$('#geminiScannerApiKey').value=key;$('#geminiScannerStatus').textContent=key?`API key saved on this device · Gemini 3.1 Flash Live · HIGH thinking.`:'API key cleared.';toast(key?'Gemini scanner key saved':'Gemini scanner key cleared');});
  $('#clearGeminiScannerKey')?.addEventListener('click',async()=>{await SC.clearApiKey();scannerHealthOkAt=0;scannerUpdateHealthOkAt=0;$('#geminiScannerApiKey').value='';$('#geminiScannerStatus').textContent='API key cleared. Scanner is disabled until a free Gemini key is added.';toast('Gemini scanner key cleared');});
  $('#testGeminiScannerKey')?.addEventListener('click',async()=>{const input=$('#geminiScannerApiKey').value.trim();if(input)await SC.setApiKey(input);const status=$('#geminiScannerStatus');status.textContent='Testing Gemini 3.1 Flash Live connection and loading 279 exact visual references…';try{const h=await SC.health();scannerHealthOkAt=Date.now();status.textContent=`Connected · ${h.provider} · HIGH thinking · ${h.playstyleReferences} exact playstyle states + ${h.colouredSpecialAbilityReferences} coloured Special Ability icons · gold SA references disabled`;toast('Gemini Flash Live scanner connected');resumeSetupBlockedQueue();}catch(err){status.textContent=err.message||'Connection failed';toast(err.message||'Connection failed','err');}});

  // ---------- Drill profile ----------
  async function renderMyDrills(){const {normal,master}=await DP.ensure();$('#normalDrillConfig').innerHTML=D.NORMAL_DRILLS.map(d=>{const s=normal.drills[d.drillId]||{unlocked:false,level:0};const options=(D.DRILL_LEVELS.levels||[]).map(l=>`<option value="${Number(l.level_id)}" ${Number(s.level)===Number(l.level_id)?'selected':''}>${esc(l.name)} +${esc(l.training_effect_percent)}%</option>`).join('');return `<div class="drill-config-row" data-drill-id="${esc(d.drillId)}" data-drill-name="${esc(d.name.toLowerCase())}" data-drill-cat="${esc(d.cat)}"><div class="drill-config-main"><img src="${drillAsset(d.name,d.cat)}"><div><b>${esc(d.name)}</b><span>${esc(d.diff)} · ${fmt(d.conditionDrop,2)}% condition · +${esc(d.xpPerPlayer)} XP</span></div></div><label class="unlock-control" title="I have this drill unlocked"><input type="checkbox" data-normal-unlock="${esc(d.drillId)}" ${s.unlocked?'checked':''}><i></i></label><select class="level-select" data-normal-level="${esc(d.drillId)}" ${s.unlocked?'':'disabled'}><option value="0" ${Number(s.level)===0?'selected':''}>Choose level</option>${options}</select></div>`;}).join('');$('#masterStockConfig').innerHTML=D.MASTER_CAMPUS_DRILLS.map(d=>`<div class="master-card"><img src="${drillAsset(d.name,d.cat)}"><div class="master-card-copy"><span class="master-badge">MASTER +${esc(d.additionalTrainingEffectPercent)}%</span><b>${esc(d.name)}</b><small>${esc(d.diff)} · ${fmt(d.conditionDrop,2)}% condition · +${esc(d.xpPerPlayer)} XP</small><small>${esc(d.skills.join(' · '))}</small></div><label><span>CARDS OWNED</span><input type="number" min="0" step="1" inputmode="numeric" data-master-stock="${esc(d.drillId)}" value="${Math.max(0,Number(master.stock[d.drillId]||0))}"></label></div>`).join('');await updateTrainingIntel();applyDrillLibraryFilter();}
  function applyDrillLibraryFilter(){const q=String($('#drillLibrarySearch')?.value||'').trim().toLowerCase(),cat=$('#drillLibraryCategory')?.value||'';document.querySelectorAll('#normalDrillConfig .drill-config-row').forEach(row=>{const name=row.dataset.drillName||'',rowCat=row.dataset.drillCat||'';row.style.display=(!q||name.includes(q))&&(!cat||rowCat===cat)?'grid':'none';});}
  $('#drillLibrarySearch')?.addEventListener('input',applyDrillLibraryFilter);$('#drillLibraryCategory')?.addEventListener('change',applyDrillLibraryFilter);
  document.addEventListener('change',async e=>{if(e.target.matches('[data-normal-unlock]')){const id=e.target.dataset.normalUnlock,row=e.target.closest('.drill-config-row'),sel=row.querySelector('[data-normal-level]'),unlocked=e.target.checked;sel.disabled=!unlocked;const level=unlocked?Number(sel.value||0):0;await DP.setNormal(id,{unlocked,level});clearTrainingSessionView();toast(`${row.querySelector('b').textContent} ${unlocked?'enabled':'locked'} · saved sessions cleared`);await updateTrainingIntel();}else if(e.target.matches('[data-normal-level]')){const id=e.target.dataset.normalLevel,row=e.target.closest('.drill-config-row'),unlock=row.querySelector('[data-normal-unlock]');const level=Number(e.target.value||0);await DP.setNormal(id,{unlocked:unlock.checked,level});clearTrainingSessionView();toast('Drill level saved · sessions cleared');}else if(e.target.matches('[data-master-stock]')){const q=await DP.setMasterStock(e.target.dataset.masterStock,e.target.value);e.target.value=q;clearTrainingSessionView();toast('Master stock saved · sessions cleared');await updateTrainingIntel();}});
  $('#resetDrillsBtn')?.addEventListener('click',async()=>{const b=$('#resetDrillsBtn');if(!b.dataset.armed){b.dataset.armed='1';b.textContent='Tap again to clear';setTimeout(()=>{delete b.dataset.armed;b.textContent='Clear setup';},3000);return;}await DP.clearUserSetup();clearTrainingSessionView();delete b.dataset.armed;b.textContent='Clear setup';toast('Your drill levels were cleared · sessions cleared');await renderMyDrills();await updateTrainingIntel();});

  // ---------- Individual training ----------
  function clearTrainingSessionView(message=''){state.session=null;if($('#trainingResults'))$('#trainingResults').style.display='none';if(message&&$('#trainingStatus'))$('#trainingStatus').textContent=message;}
  function trainingSourceSnapshot(player,normal,master,plan=null){const starter=plan?.starters?.find(x=>x.playerKey===player?.key);return {playerUpdatedAt:String(player?.updatedAt||''),normalUpdatedAt:String(normal?.updatedAt||''),masterUpdatedAt:String(master?.updatedAt||''),teamPlanVersion:Number(plan?.version||0),formationTemplateId:String(plan?.formationTemplateId||''),assignedRole:String(starter?.assignedRole||''),tactics:JSON.stringify(plan?.tactics?.values||{})};}
  function sameTrainingSource(a,b){return !!a&&a.playerUpdatedAt===b.playerUpdatedAt&&a.normalUpdatedAt===b.normalUpdatedAt&&a.masterUpdatedAt===b.masterUpdatedAt&&Number(a.teamPlanVersion||0)===Number(b.teamPlanVersion||0)&&String(a.formationTemplateId||'')===String(b.formationTemplateId||'')&&String(a.assignedRole||'')===String(b.assignedRole||'')&&String(a.tactics||'{}')===String(b.tactics||'{}');}
  async function updateTrainingIntel(){const {normal,master}=await DP.ensure();const drills=normal&&typeof normal.drills==='object'&&normal.drills?normal.drills:{},stock=master&&typeof master.stock==='object'&&master.stock?master.stock:{};const unlocked=Object.values(drills).filter(x=>x&&x.unlocked).length,totalMaster=Object.values(stock).reduce((a,b)=>a+Math.max(0,Number(b)||0),0);if($('#drillSummaryUnlocked'))$('#drillSummaryUnlocked').textContent=unlocked;if($('#drillSummaryMaster'))$('#drillSummaryMaster').textContent=totalMaster;if($('#drillSummaryTotal'))$('#drillSummaryTotal').textContent=D.NORMAL_DRILLS.length;}
  async function renderTrainingPicker(){await updateTrainingIntel();const players=await P.all();$('#trainingPlayer').innerHTML='<option value="">Select a player</option>'+players.map(p=>`<option value="${esc(p.key)}" ${p.key===state.trainingKey?'selected':''}>${esc(p.name)} · ${esc(rolesLabel(p))} · ${esc(p.ovr||'—')} OVR</option>`).join('');clearTrainingSessionView();$('#trainingStatus').textContent=state.trainingKey?'Ready to generate a fresh 6-drill session.':'Select a player, choose a mode, then generate the session.';if(state.trainingKey&&!players.some(p=>p.key===state.trainingKey)){state.trainingKey='';$('#trainingStatus').textContent='Select a player, choose a mode, then generate the session.';return;}refreshThemedSelects();}
  async function persistTraining(){if(!state.trainingKey||!state.session)return;await S.set(`training:session:${state.trainingKey}`,JSON.stringify({gameDataVersion:D.GAME_DATA_VERSION,session:state.session,savedAt:new Date().toISOString()}));}
  async function restoreTrainingSession(){clearTrainingSessionView();const key=`training:session:${state.trainingKey}`,raw=await S.get(key);if(!raw)return false;try{const x=JSON.parse(raw);if(x.gameDataVersion!==D.GAME_DATA_VERSION||x.session?.meta?.model!==T.MODEL_VERSION){await S.del(key);$('#trainingStatus').textContent='A previous recommendation used older training data. Build a fresh session.';return false;}const player=await P.get(state.trainingKey);if(!player){await S.del(key);return false;}const {normal,master}=await DP.ensure(),plan=await TP.load(),current=trainingSourceSnapshot(player,normal,master,plan);if(!sameTrainingSource(x.session?.sourceSnapshot,current)){await S.del(key);$('#trainingStatus').textContent='Saved recommendation expired because the player or My Drills changed. Build a fresh session.';return false;}state.session=x.session;const mode=$('#trainingMode');if(mode&&[...mode.options].some(o=>o.value===state.session?.meta?.mode))mode.value=state.session.meta.mode;renderSession();$('#trainingStatus').textContent=state.session.completed?'Completed session restored.':'Saved recommendation restored.';return true;}catch(_){await S.del(key);$('#trainingStatus').textContent='Saved recommendation could not be restored. Build a fresh session.';return false;}}
  $('#trainingPlayer')?.addEventListener('change',e=>{state.trainingKey=e.target.value;persistUiState();clearTrainingSessionView(state.trainingKey?'Ready to generate a fresh 6-drill session.':'Select a player, choose a mode, then generate the session.');});
  async function buildTrainingCore(){if(!state.trainingKey){toast('Select a player first','err');return;}const player=await P.get(state.trainingKey);if(!player){toast('Player could not be loaded','err');return;}const {normal,master}=await DP.ensure(),plan=await TP.load(),starter=plan?.starters?.find(x=>x.playerKey===player.key)||null,naturalRoles=P.normaliseRoles(player),developmentRole=starter?.assignedRole||null,tactics=starter&&plan?.tactics?.values?plan.tactics:null;const result=T.buildIndividualSession({player,roles:naturalRoles,developmentRole,tactics,normalProfile:normal,masterStock:master,slots:6,mode:$('#trainingMode')?.value||'maxGrowth'});if(result.error==='missing-white-attributes'){$('#trainingStatus').textContent=`Cannot optimise reliably: ${result.missingAttributes.join(', ')} are missing from this player profile. Rescan or update the player first.`;$('#trainingResults').style.display='none';toast('Player profile is incomplete','err');return;}state.session={...result,playerKey:state.trainingKey,playerName:player.name,teamPlanContext:starter?{formation:plan.formationName,assignedRole:starter.assignedRole,developmentRole:result.meta.hierarchy.developmentRole,developmentRoleFallbackReason:result.meta.hierarchy.developmentRoleFallbackReason||null,tactics:plan.tactics?.values||null}:null,completed:false,stockDeducted:false,createdAt:new Date().toISOString(),sourceSnapshot:trainingSourceSnapshot(player,normal,master,plan)};renderSession();await persistTraining();const identity=`${result.meta.hierarchy.developmentRole}${result.meta.hierarchy.playstyle?` + ${result.meta.hierarchy.playstyle}`:''}`,relatedFallback=starter&&result.meta.hierarchy.developmentRoleFallbackReason?` The Team Plan fields him at ${starter.assignedRole}, but that is not one of his natural trained roles, so development safely uses natural ${result.meta.hierarchy.developmentRole}.`:'',planText=starter?` using the current ${plan.formationName} Team Plan tactics`:' using the player profile because this player is not in the current XI',modeLabel=result.meta.mode==='balancedDevelopment'?'Balanced Development':result.meta.mode==='conditionEfficient'?'Condition Efficient':'Max Growth',modeReason=result.meta.mode==='balancedDevelopment'?' This mode deliberately prioritises broader weak-white coverage and distinct drills before raw utility.':result.meta.mode==='conditionEfficient'?' This mode prioritises useful training utility per condition.':' This mode prioritises maximum total useful white-skill utility.';$('#trainingStatus').textContent=result.drills.length===6?`Built 6 slots for ${identity}${planText}. ${modeLabel}.${modeReason}${relatedFallback} The verified drill gain ladder still determines drill strength; grey attributes remain zero-value.`:`Only ${result.drills.length}/6 legal slots could be built from your saved drill library.`;}
  async function buildTraining(){return runUiAction('training-build',['#buildSessionBtn','#rebuildBtn'],buildTrainingCore);}
  $('#buildSessionBtn')?.addEventListener('click',()=>void buildTraining());$('#rebuildBtn')?.addEventListener('click',()=>void buildTraining());$('#trainingMode')?.addEventListener('change',()=>{if(state.session){clearTrainingSessionView('Training mode changed. Build a fresh 6-drill session.');}});
  function masterProjectionHtml(r){const usage=Object.entries(r.meta?.masterUsage||{}).filter(([,n])=>Number(n)>0);if(!usage.length)return'';return `<div class="master-projection wide"><span>Master stock ${r.completed?'remaining':'projection'}</span><div>${usage.map(([id,n])=>{const name=D.MASTER_CAMPUS_DRILLS.find(d=>d.drillId===id)?.name||id,used=Number(n)||0,remaining=Number(r.meta?.remainingMasterStock?.[id]??0),owned=remaining+used;return `<section><b>${esc(name)}</b><small>${owned} owned at build</small><strong>${used} used</strong><em>${remaining} ${r.completed?'remaining now':'projected remaining'}</em></section>`;}).join('')}</div></div>`;}
  function renderSession(){const r=state.session;if(!r)return;$('#trainingResults').style.display='grid';const priority=(r.meta?.priorityAttributes||[]);$('#priorityAttributes').innerHTML=priority.map((x,i)=>`<div class="priority-pill"><span>${i+1}</span><b>${esc(x.attribute)} · ${esc(x.tier||'')}</b><small>${esc(x.value)} → target ${fmt(x.target,0)} · gap ${fmt(x.gap,0)}</small></div>`).join('');const masterSeen={};$('#sessionList').innerHTML=r.drills?.length?r.drills.map((d,i)=>{let stockLine='';if(d.isMaster){masterSeen[d.drillId]=(masterSeen[d.drillId]||0)+1;const used=Number(r.meta?.masterUsage?.[d.drillId]||0),remaining=Number(r.meta?.remainingMasterStock?.[d.drillId]??0),owned=remaining+used;stockLine=`<div class="master-use-line">Card ${masterSeen[d.drillId]}/${used} · ${owned} owned · ${remaining} ${r.completed?'remaining':'left after this session'}</div>`;}const grey=(d.greyApplicableAttributes||[]);const greyLine=grey.length?`<div class="grey-info"><span>Grey / information only · zero score</span>${grey.map(a=>`<i>${esc(a)}</i>`).join('')}</div>`:'';return `<div class="drill-row ${drillCategoryClass(d.cat)} ${d.isMaster?'master':''}"><div class="slot-no">${String(i+1).padStart(2,'0')}</div><img src="${drillAsset(d.name,d.cat)}"><div class="drill-copy"><div class="drill-title-line"><b>${esc(d.name)}</b><span class="drill-category-badge">${esc(drillCategoryLabel(d.cat))}</span>${d.isMaster?'<span class="master-badge small">MASTER</span>':''}</div><small>${esc(d.diff)} · base +${esc(d.xpPerPlayer)} XP · ${d.isMaster?`+${d.effectPct}% Training Effect`:`${esc(d.levelName)} +${d.effectPct}%`} · effective gain ${fmt(d.strength,1)} · ${fmt(d.conditionDrop,2)}% condition</small>${stockLine}<div class="target-line"><span>Targets · ${d.targetedWhiteAttributes.length} white</span>${d.targetedWhiteAttributes.map(a=>`<i>${esc(a)}</i>`).join('')}</div>${greyLine}</div><span class="diff ${diffClass(d.diff)}">${esc(d.diff)}</span></div>`;}).join(''):'<div class="empty"><b>No legal session</b>Check My Drills and the selected player profile.</div>';$('#sessionSummary').innerHTML=`<div><span>Total condition</span><b>${fmt(r.meta?.totalCondition,2)}%</b></div><div><span>Total XP</span><b>${fmt(r.meta?.totalXp,0)}</b></div><div><span>Recommendation score</span><b>${fmt(r.meta?.totalUsefulScore,1)}</b></div>${masterProjectionHtml(r)}<p><strong>Top Eleven Tool calculation.</strong> The recommendation deliberately shapes this player toward the selected Role+Playstyle profile: S-tier white skills are meant to sit above A/B skills, while current Team Plan tactics only add a small capped bias. Grey attributes have zero utility. Drill strength uses the verified Very Easy→Very Hard base-XP ladder 1→5 plus the saved drill-level effect, so harder drills produce more modelled training gain when they hit the right white skills. Exact final attribute gains remain server-authoritative, so this is a ranking model rather than a predicted +X% result. ${r.meta?.mode==='balancedDevelopment'?'Balanced Development prioritises broad weak-white coverage and distinct drills before raw utility. ':r.meta?.mode==='conditionEfficient'?'Condition Efficient prioritises useful utility per condition. ':'Max Growth prioritises total useful white-skill utility. '}</p>`;$('#completeSessionBtn').disabled=!!r.completed;$('#completeSessionBtn').textContent=r.completed?'Session Completed ✓':'Mark Session Completed';$('#sessionCompleteNote').textContent=r.completed?(r.stockDeducted?'Master card stock has been deducted once; the remaining figures above are current.':'Completed. No Master cards were used.'):'Master figures above are projected only. Stock changes when you complete the whole session.';}
  $('#completeSessionBtn')?.addEventListener('click',async()=>{if(!state.session||state.session.completed)return;const usage=state.session.meta?.masterUsage||{};if(Object.values(usage).some(n=>Number(n)>0)&&!state.session.stockDeducted){const updatedMaster=await DP.deductMasterUsage(usage);state.session.stockDeducted=true;if(state.session.sourceSnapshot)state.session.sourceSnapshot.masterUpdatedAt=String(updatedMaster.updatedAt||'');}state.session.completed=true;state.session.completedAt=new Date().toISOString();await persistTraining();renderSession();await updateTrainingIntel();toast('Training session completed');});

  // ---------- Team normal-drill group planner ----------
  let teamTrainingRenderSeq=0;
  function teamTrainingCardHtml(key,g,r){
    if(r.error)return `<article class="team-card training-team-card" data-team-group="${esc(key)}"><div class="team-card-top"><span class="team-card-icon"><img src="assets/icons/team.svg" alt=""></span><div><span>SQUAD GROUP</span><b>${esc(g.title)}</b></div></div><div class="mini-note spaced team-card-empty">${r.error==='no-complete-players'?'No complete player profiles in this group.':esc(r.error)}</div></article>`;
    return `<article class="team-card training-team-card" data-team-group="${esc(key)}"><div class="team-card-top"><span class="team-card-icon"><img src="assets/icons/team.svg" alt=""></span><div><span>SQUAD GROUP</span><b>${esc(g.title)}</b></div><em>${r.meta.selectedPlayerCount} PLAYERS</em></div><div class="team-mini-list">${r.drills.map((d,i)=>`<div class="team-drill-item ${drillCategoryClass(d.cat)} ${d.isMaster?'master':''}"><span class="team-drill-no">${String(i+1).padStart(2,'0')}</span><img src="${drillAsset(d.name,d.cat)}" alt=""><div class="team-drill-copy"><span class="drill-category-badge">${esc(drillCategoryLabel(d.cat))}</span><b>${esc(d.name)}</b><small>${esc(d.diff)} · ${d.usefulHits} useful hits</small></div><strong>+${d.effectPct}%</strong></div>`).join('')}</div><footer class="team-card-summary"><span><small>CONDITION</small><b>${fmt(r.meta.totalCondition,2)}%</b></span><span><small>UTILITY SCORE</small><b>${fmt(r.meta.totalUsefulScore,1)}</b></span></footer></article>`;
  }
  async function renderTeamTraining(){
    const grid=$('#teamTrainingCards');if(!grid)return;
    const request=++teamTrainingRenderSeq;
    const groups=Object.entries(D.TEAM_GROUPS);
    grid.setAttribute('aria-busy','true');
    grid.innerHTML=groups.map(([,g])=>`<article class="team-card training-team-card team-card-loading"><div class="team-card-top"><span class="team-card-icon"><img src="assets/icons/team.svg" alt=""></span><div><span>BUILDING SESSION</span><b>${esc(g.title)}</b></div></div><div class="team-loading-bar"><i></i></div></article>`).join('');
    const normal=await DP.getNormal(),players=await P.all(),plan=await TP.load();
    if(request!==teamTrainingRenderSeq||state.trainingTab!=='team')return;
    const cards=[];
    for(const [key,g] of groups){
      await new Promise(resolve=>setTimeout(resolve,0));
      if(request!==teamTrainingRenderSeq||state.trainingTab!=='team')return;
      const r=TT.buildTeamSession(key,{normalProfile:normal,players,teamPlan:plan});
      cards.push(teamTrainingCardHtml(key,g,r));
      grid.innerHTML=cards.join('')+groups.slice(cards.length).map(([,pending])=>`<article class="team-card training-team-card team-card-loading"><div class="team-card-top"><span class="team-card-icon"><img src="assets/icons/team.svg" alt=""></span><div><span>BUILDING SESSION</span><b>${esc(pending.title)}</b></div></div><div class="team-loading-bar"><i></i></div></article>`).join('');
    }
    grid.removeAttribute('aria-busy');
  }
  function setTrainingTab(tab){
    if(!['individual','team'].includes(tab))tab='individual';
    state.trainingTab=tab;persistUiState();
    $$('[data-training-tab]').forEach(b=>{const active=b.dataset.trainingTab===tab;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false');});
    $('#individualTrainingPanel').style.display=tab==='individual'?'block':'none';
    $('#teamTrainingPanel').style.display=tab==='team'?'block':'none';
    if(tab==='team')setTimeout(()=>renderTeamTraining(),0);else teamTrainingRenderSeq++;
  }
  document.addEventListener('click',e=>{const b=e.target.closest('[data-training-tab]');if(b)setTrainingTab(b.dataset.trainingTab);});

  // ---------- Team Plan ----------
  const SET_PIECES_KEY='teamplan:setpieces:v5',LEGACY_SET_PIECES_V4_KEY='teamplan:setpieces:v4',LEGACY_SET_PIECES_V3_KEY='teamplan:setpieces:v3',LEGACY_SET_PIECES_V2_KEY='teamplan:setpieces:v2',MENTOR_STATE_KEY='mentor:state:v2',UI_RESTRUCTURE_KEY='migration:ui:v045';
  const SET_PIECE_MODES=[['cornerRight','Corner Kick R'],['freeRight','Free Kick R'],['penalty1','Penalty Kick'],['freeLeft','Free Kick L'],['cornerLeft','Corner Kick L'],['penalty2','Penalty #2'],['penalty3','Penalty #3'],['penalty4','Penalty #4'],['penalty5','Penalty #5'],['captain','Captain']];
  const SET_PIECE_LAYOUT={cornerRight:[9,10],freeRight:[31,30],penalty1:[18,50],freeLeft:[31,70],cornerLeft:[9,90],penalty2:[55,12],penalty3:[55,36],penalty4:[55,60],penalty5:[55,84],captain:[82,50]};
  const TACTIC_PHASES={possession:{title:'In Possession',dims:['shooting','passing','focus','cross']},transition:{title:'In Transition',dims:['lost','won','mentality']},out:{title:'Out of Possession',dims:['marking','pressing','backLine','tackling']}};
  const TACTIC_LABELS={passing:'Passing style',shooting:'Shooting tendency',focus:'Focus passing',cross:'Cross tendency',lost:'Possession lost',won:'Possession won',mentality:'Mentality',marking:'Marking style',pressing:'Pressing',backLine:'Back line',tackling:'Tackling style'};
  let currentTeamPlan=null,currentSetPieceState=null,currentSetPieces={};
