  document.addEventListener('click',async e=>{const tab=e.target.closest('[data-team-plan-tab]');if(tab){setTeamPlanTab(tab.dataset.teamPlanTab);return;}const phase=e.target.closest('[data-tactic-phase]');if(phase){setTacticPhase(phase.dataset.tacticPhase);return;}const formationPlayer=e.target.closest('#formationPitch [data-player-key]');if(formationPlayer){state.playerKey=formationPlayer.dataset.playerKey;persistUiState();go('player');return;}const step=e.target.closest('[data-mentor-step]');if(step){const id=step.dataset.mentorId,input=document.querySelector(`[data-mentor-level="${CSS.escape(id)}"]`),next=await setMentorLevel(id,Number(input?.value||1)+Number(step.dataset.mentorStep||0));if(input)input.value=next;await updatePlanOnly();return;}});
